#!/usr/bin/env node
/**
 * Builds the **whole** GitHub Pages site into `_site/`:
 *
 *   _site/
 *     index.html            the public page (generated by `scripts/build-site.mjs`)
 *     404.html              served by GitHub Pages for any unknown address
 *     favicon.svg           the application's own icon
 *     app/                  the installable web application (Vite build)
 *       index.html, assets/, icons/, manifest.webmanifest, sw.js, …
 *
 * Why one directory, and why the application under `app/`: GitHub Pages serves exactly
 * one thing per repository, at `https://<owner>.github.io/<repo>/`. The public page
 * keeps the root (it is the address people share), and the application lives one click
 * below, on the **same origin** — which is what makes the service worker, the manifest
 * and the install prompt work without a second host.
 *
 * The base path is the repository's, not the domain's. Everything the application
 * references is written with that prefix (`/DROPForge/app/assets/…`), and everything the
 * pages reference is **relative** (`app/`), so a fork publishes itself correctly.
 *
 * Nothing is published that has not been produced here: this script owns `_site/`
 * entirely and refuses to leave a source map or an oversized file behind.
 */
import { execFileSync } from 'node:child_process';
import { cpSync, existsSync, mkdirSync, readdirSync, readFileSync, rmSync, statSync, writeFileSync } from 'node:fs';
import { join, relative } from 'node:path';
import { fileURLToPath } from 'node:url';
import { APP_PATH, SITE_URL, buildSiteFiles } from './build-site.mjs';

const root = fileURLToPath(new URL('..', import.meta.url));
const OUT = '_site';
const APP_DIR = APP_PATH.replace(/\/$/, '');
const METADATA = '.pages-build.json';

/** Budget of the published site. GitHub Pages allows 1 GB; this is a warning line, not a limit. */
const TOTAL_BUDGET_BYTES = 4 * 1024 * 1024;
const FILE_BUDGET_BYTES = 1.5 * 1024 * 1024;

const say = (message) => console.log(`[pages] ${message}`);
const fail = (message) => {
  console.error(`[pages] ${message}`);
  process.exitCode = 1;
};

/** `/DROPForge`, `DROPForge/`, `/` → `/DROPForge/`, `/DROPForge/`, `/`. */
function normalizeBase(value) {
  const trimmed = value.trim().replace(/^\/+|\/+$/g, '');
  return trimmed === '' ? '/' : `/${trimmed}/`;
}

/** Every file under a directory, with its path relative to it. */
function walk(directory, prefix = '') {
  const out = [];
  for (const entry of readdirSync(directory, { withFileTypes: true })) {
    const absolute = join(directory, entry.name);
    const path = prefix === '' ? entry.name : `${prefix}/${entry.name}`;
    if (entry.isDirectory()) out.push(...walk(absolute, path));
    else if (entry.isFile()) out.push({ path, absolute, size: statSync(absolute).size });
  }
  return out.sort((a, b) => a.path.localeCompare(b.path));
}

const base = normalizeBase(process.env['DROPFORGE_PAGES_BASE'] ?? '/DROPForge/');
const appBase = `${base}${APP_PATH}`;
const siteUrl = process.env['DROPFORGE_SITE_URL'] ?? SITE_URL;
const version = JSON.parse(readFileSync(join(root, 'package.json'), 'utf8')).version;

/* ------------------------------------------------------------------ *
 * 1. The application, built for its real address
 * ------------------------------------------------------------------ */

say(`application : base ${appBase}`);
execFileSync(process.platform === 'win32' ? 'npm.cmd' : 'npm', ['run', 'build:web'], {
  cwd: root,
  stdio: 'inherit',
  shell: process.platform === 'win32',
  env: {
    ...process.env,
    DROPFORGE_BASE: appBase,
    DROPFORGE_VERSION: version,
    // A published site is not a debug build: source maps would add megabytes to every
    // download (2.8 MB for a 600 KB bundle) and publish the sources with them. They are
    // opt-in (`DROPFORGE_SOURCEMAP=1`) for someone who needs them.
    DROPFORGE_SOURCEMAP: process.env['DROPFORGE_SOURCEMAP'] ?? '0',
  },
});

/* ------------------------------------------------------------------ *
 * 2. Assemble the site
 * ------------------------------------------------------------------ */

rmSync(join(root, OUT), { recursive: true, force: true });
mkdirSync(join(root, OUT), { recursive: true });
cpSync(join(root, 'apps', 'web', 'dist'), join(root, OUT, APP_DIR), { recursive: true });

if (!existsSync(join(root, OUT, APP_DIR, 'index.html'))) throw new Error('application absente de la construction');
if (!readFileSync(join(root, OUT, APP_DIR, 'index.html'), 'utf8').includes(appBase)) {
  throw new Error(
    `l'application a été construite sans son chemin (${appBase}) : ses fichiers pointeraient dans le vide. ` +
      'Vérifiez DROPFORGE_BASE.',
  );
}

const pages = await buildSiteFiles({ root, appUrl: APP_PATH, base, siteUrl });
for (const [name, content] of pages) {
  writeFileSync(join(root, OUT, name), content, 'utf8');
}

/* ------------------------------------------------------------------ *
 * 3. Refuse what should not be published
 * ------------------------------------------------------------------ */

const files = walk(join(root, OUT));
const maps = files.filter((file) => file.path.endsWith('.map'));
if (maps.length > 0) fail(`cartes de sources publiées alors qu'elles ne devraient pas l'être : ${maps.map((f) => f.path).join(', ')}`);

const tooBig = files.filter((file) => file.size > FILE_BUDGET_BYTES);
for (const file of tooBig) fail(`fichier trop lourd : ${file.path} (${(file.size / 1024).toFixed(0)} Kio)`);

const total = files.reduce((sum, file) => sum + file.size, 0);
if (total > TOTAL_BUDGET_BYTES) fail(`site trop lourd : ${(total / 1024 / 1024).toFixed(2)} Mio pour un budget de 4 Mio`);

// The build metadata tells the checks (and a human) what was built, without shipping a
// file to the published site.
writeFileSync(
  join(root, METADATA),
  `${JSON.stringify({ base, appBase, siteUrl, version, builtAt: new Date().toISOString(), files: files.length, bytes: total }, null, 2)}\n`,
  'utf8',
);

say(`${files.length} fichiers, ${(total / 1024).toFixed(0)} Kio au total`);
for (const file of [...files].sort((a, b) => b.size - a.size).slice(0, 5)) {
  say(`  ${(file.size / 1024).toFixed(0).padStart(6)} Kio  ${relative(join(root, OUT), file.absolute)}`);
}
if (process.exitCode === 1) {
  // The directory is on disk for inspection, but it is not announced as ready: a
  // build that failed one of its own rules must not be the one that gets published.
  console.error(`[pages] site INCOMPLET : ${join(OUT, 'index.html')} ne doit pas être publié.`);
} else {
  say(`site prêt : ${join(OUT, 'index.html')} (application : ${base}${APP_PATH})`);
}
